#include "editor/EditorAssetBrowser.h"
#include <algorithm>
#include <cctype>
namespace subspace {namespace{std::string Lower(std::string s){for(auto&c:s)c=static_cast<char>(std::tolower(static_cast<unsigned char>(c)));return s;}bool Has(const std::string&a,const std::string&b){return Lower(a).find(Lower(b))!=std::string::npos;}}
std::vector<EditorAssetCard>EditorAssetBrowserModel::Filtered(const EditorAssetBrowserFilter&f)const{std::vector<EditorAssetCard>o;for(const auto&a:assets_){if(!f.category.empty()&&a.category!=f.category)continue;if(f.favoritesOnly&&!IsFavorite(a.assetId))continue;if(f.recentOnly&&std::find(recent_.begin(),recent_.end(),a.assetId)==recent_.end())continue;if(f.reviewOnly&&a.badge!="REVIEW"&&std::find(a.tags.begin(),a.tags.end(),"review")==a.tags.end())continue;if(!f.query.empty()&&!Has(a.displayName,f.query)&&!Has(a.assetId,f.query)&&!Has(a.subtitle,f.query))continue;bool tags=true;for(const auto&t:f.requiredTags)if(std::find(a.tags.begin(),a.tags.end(),t)==a.tags.end()){tags=false;break;}if(tags)o.push_back(a);}return o;}void EditorAssetBrowserModel::SetFavorite(const std::string&id,bool f){if(f)favorites_.insert(id);else favorites_.erase(id);}void EditorAssetBrowserModel::MarkRecent(const std::string&id){recent_.erase(std::remove(recent_.begin(),recent_.end(),id),recent_.end());recent_.insert(recent_.begin(),id);if(recent_.size()>16)recent_.resize(16);}bool EditorDragSession::Begin(EditorDragPayload p){if(p.kind==EditorDragPayloadKind::None||p.assetId.empty())return false;payload_=std::move(p);active_=true;return true;}void EditorDragSession::Cancel(){active_=false;payload_={};}float EditorPlacementCandidate::TotalScore()const{return compatibilityScore*4+orientationScore*2+designScore-distanceScore*1.5f-(collision?10000:0)-(clearanceBlocked?5000:0);}EditorPlacementResolution EditorPlacementResolver::Resolve(std::vector<EditorPlacementCandidate>c){EditorPlacementResolution o;if(c.empty()){o.state=EditorPlacementState::Invalid;o.message="No compatible mount found";return o;}std::sort(c.begin(),c.end(),[](const auto&a,const auto&b){return a.TotalScore()>b.TotalScore();});o.ranked=std::move(c);o.selectedIndex=0;const auto&b=o.ranked.front();if(b.collision){o.state=EditorPlacementState::Invalid;o.message=b.invalidReason.empty()?"Placement intersects existing geometry":b.invalidReason;}else if(b.clearanceBlocked){o.state=EditorPlacementState::Invalid;o.message=b.invalidReason.empty()?"Required clearance is blocked":b.invalidReason;}else if(!b.warning.empty()){o.state=EditorPlacementState::Warning;o.message=b.warning;}else{o.state=EditorPlacementState::Valid;o.message="Compatible mount ready";}return o;}}
